// Aggregate per-volume summaries into a master record
const volumes = $input.all().map(i => i.json);
const total_code = volumes.reduce((s, v) => s + Object.values(v.code || {}).reduce((a, b) => a + b, 0), 0);
const total_secrets = volumes.reduce((s, v) => s + (v.secrets_pattern_count || 0), 0);
const total_audio = volumes.reduce((s, v) => s + Object.values(v.media || {}).reduce((a, b) => a + b, 0), 0);
return [{ json: {
  scanned_at: new Date().toISOString(),
  volume_count: volumes.length,
  total_code_projects: total_code,
  total_secret_pattern_files: total_secrets,
  total_audio_files: total_audio,
  per_volume: volumes.map(v => ({
    volume: v.volume,
    size: v.size,
    code: Object.values(v.code || {}).reduce((a, b) => a + b, 0),
    secrets: v.secrets_pattern_count,
    audio: Object.values(v.media || {}).reduce((a, b) => a + b, 0),
    audit: v.audit_path
  }))
} }];
